@namespace sv_c61e1c4254d2433ebee5d4760dced8a9.Components.Pages.Apply

<div class="form-step">
    <h2>References</h2>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <div class="reference-card">
            <div class="reference-header">
                <h4>Reference @(index + 1)</h4>
                @if (References.Count > 2)
                {
                    <button class="btn btn-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>

            <div class="form-group">
                <label>Name *</label>
                <input type="text" value="@References[index].Name"
                       @oninput="e => UpdateField(index, e, \"Name\")" class="form-control" />
            </div>

            <div class="form-group">
                <label>Relationship *</label>
                <input type="text" value="@References[index].Relationship"
                       @oninput="e => UpdateField(index, e, \"Relationship\")" class="form-control" />
            </div>

            <div class="form-row">
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" value="@References[index].Email"
                           @oninput="e => UpdateField(index, e, \"Email\")" class="form-control" />
                </div>

                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" value="@References[index].Phone"
                           @oninput="e => UpdateField(index, e, \"Phone\")" class="form-control" />
                </div>
            </div>
        </div>
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(validationError))
    {
        <div class="validation-summary">@validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? validationError;

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private void UpdateField(int index, ChangeEventArgs e, string field)
    {
        var value = e.Value?.ToString() ?? "";
        References[index] = field switch
        {
            "Name" => References[index] with { Name = value },
            "Relationship" => References[index] with { Relationship = value },
            "Email" => References[index] with { Email = value },
            "Phone" => References[index] with { Phone = value },
            _ => References[index]
        };
    }

    private async Task HandleNext()
    {
        validationError = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                validationError = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync(References);
    }

    public record ReferenceModel
    {
        public string Name { get; init; } = "";
        public string Relationship { get; init; } = "";
        public string Email { get; init; } = "";
        public string Phone { get; init; } = "";
    }
}

